import pickle

def square_sum(numbers):
    return sum(n * n for n in numbers)

def show_the_copy():
    items = [1, 2, 3]
    received = pickle.loads(pickle.dumps(items))
    received.append(4)
    print(items, received, received is items)
    try:
        pickle.dumps(lambda n: n * n)
    except (pickle.PicklingError, AttributeError):
        print("a lambda cannot be sent to another process")

if __name__ == "__main__":
    show_the_copy()
    chunks = [range(0, 500_000), range(500_000, 1_000_000)]
    try:
        from concurrent.futures import ProcessPoolExecutor
        with ProcessPoolExecutor() as pool:
            print(sum(pool.map(square_sum, chunks)))
    except ImportError as err:
        print("this runtime cannot start processes:", type(err).__name__)

