def interleave(schedule):
    counter = 0
    register = {"A": 0, "B": 0}
    next_is_load = {"A": True, "B": True}
    for thread in schedule:
        if next_is_load[thread]:
            register[thread] = counter
        else:
            counter = register[thread] + 1
        next_is_load[thread] = not next_is_load[thread]
    return counter

