def estimate(jobs, model, cores):
    total_cpu = sum(cpu for cpu, wait in jobs)
    longest_job = max((cpu + wait for cpu, wait in jobs), default=0)
    if model == "serial":
        return round(sum(cpu + wait for cpu, wait in jobs), 2)
    if model in ("threads", "async"):
        return round(max(total_cpu, longest_job), 2)
    if model == "processes":
        return round(max(total_cpu / cores, longest_job), 2)

def run_loop(tasks):
    clock = 0
    ready = [[0, position, name, 0] for position, name in enumerate(tasks)]
    finished = {}
    while ready:
        ready.sort()
        ready_at, position, name, index = ready.pop(0)
        clock = max(clock, ready_at)
        steps = tasks[name]
        suspended = False
        while index < len(steps) and not suspended:
            kind, ticks = steps[index]
            index += 1
            if kind == "cpu":
                clock += ticks
            else:
                ready.append([clock + ticks, position, name, index])
                suspended = True
        if not suspended:
            finished[name] = clock
    return finished

