def stale_writes(log):
    last_read = {}
    writes = []
    stale = []
    for position, (worker, op) in enumerate(log):
        if op == "read":
            last_read[worker] = position
        else:
            seen_at = last_read.get(worker, -1)
            for written_at, writer in writes:
                if written_at > seen_at and writer != worker:
                    stale.append(position)
                    break
            writes.append((position, worker))
    return stale

