def repeated(ids):
    seen = set()
    counted = set()
    for i in ids:
        if i in seen:
            counted.add(i)
        seen.add(i)
    return len(counted)

def best_workers(items, item_ms, startup_ms, cores):
    best, best_time = 1, items * item_ms
    for k in range(2, cores + 1):
        largest_share = -(-items // k)
        time_taken = k * startup_ms + largest_share * item_ms
        if time_taken < best_time:
            best, best_time = k, time_taken
    return best

