def plan(jobs, cores, startup):
    total_cpu = sum(cpu for cpu, wait in jobs)
    longest_job = max((cpu + wait for cpu, wait in jobs), default=0)
    options = [
        ("serial", sum(cpu + wait for cpu, wait in jobs)),
        ("threads", max(total_cpu, longest_job)),
        ("processes", max(total_cpu / cores, longest_job) + startup),
    ]
    best_name, best_time = options[0]
    for name, seconds in options[1:]:
        if seconds < best_time:
            best_name, best_time = name, seconds
    return best_name

